import csv, collections
tsids={}
with open(CATALOG_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        if 'Zone_F4_Z05' in row['point_uri']:
            tsids[row['point_class']]=row['timeseries_id']
tsid=tsids['Occupancy_Sensor']
hour=collections.defaultdict(float)
with open(VALUES_CSV) as f:
    r=csv.DictReader(f)
    for row in r:
        if row['timeseries_id']==tsid:
            ts=row['timestamp']
            if ts[:10]=='2018-10-03':
                hour[int(ts[11:13])]+=float(row['value'])
mx=max(hour.values())
best=sorted([h for h in hour if hour[h]==mx])[0]
print('best',best,mx)
print(dict(sorted(hour.items())))
